package com.bjjj.todo;
import android.content.*;import android.util.AtomicFile;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;
public final class Store {
 static AtomicFile file(Context c){return new AtomicFile(new File(c.getFilesDir(),"tasks.json"));}
 public static synchronized JSONObject read(Context c){try{return new JSONObject(new String(file(c).readFully(),StandardCharsets.UTF_8));}catch(FileNotFoundException e){try{return new JSONObject("{\"version\":1,\"tasks\":[],\"settings\":{\"opacity\":85}}");}catch(Exception x){throw new IllegalStateException(x);}}catch(Exception e){throw new IllegalStateException("数据无法读取，请保留应用数据并从备份恢复",e);}}
 public static synchronized void write(Context c,JSONObject root){FileOutputStream out=null;AtomicFile f=file(c);try{out=f.startWrite();out.write(root.toString().getBytes(StandardCharsets.UTF_8));f.finishWrite(out);}catch(Exception e){if(out!=null)f.failWrite(out);throw new IllegalStateException("保存失败",e);}}
 public static long due(JSONObject t){try{return Instant.parse(t.optString("due")).toEpochMilli();}catch(Exception e){return Long.MAX_VALUE;}}
 public static List<JSONObject> open(JSONObject root){List<JSONObject> list=new ArrayList<>();JSONArray a=root.optJSONArray("tasks");if(a!=null)for(int n=0;n<a.length();n++){JSONObject t=a.optJSONObject(n);if(t!=null&&!t.optBoolean("done"))list.add(t);}list.sort(Comparator.comparingLong(Store::due));return list;}
 public static synchronized JSONObject save(Context c,JSONObject input)throws Exception{JSONObject root=read(c);JSONArray a=root.getJSONArray("tasks");String id=input.optString("id"),title=input.optString("title").trim();if(title.isEmpty()||title.length()>200)throw new Exception("事项名称需为1–200字");JSONObject old=null;for(int i=0;i<a.length();i++)if(a.getJSONObject(i).optString("id").equals(id))old=a.getJSONObject(i);if(!id.isEmpty()&&old==null)throw new Exception("事项不存在");String priority=input.optString("priority","normal"),category=input.optString("category","other");if(!Arrays.asList("high","normal","low").contains(priority)||!Arrays.asList("research","work","study","life","other").contains(category))throw new Exception("无效的等级或类型");String date=input.optString("due","");if(!date.isEmpty())Instant.parse(date);JSONArray offsets=input.optJSONArray("offsets");if(offsets==null)offsets=new JSONArray();if(offsets.length()>20)throw new Exception("最多20个提醒");for(int n=0;n<offsets.length();n++){double value=offsets.getDouble(n);if(!Double.isFinite(value)||value<0||value>5256000)throw new Exception("提醒时间无效");}boolean same=old!=null&&old.optString("due").equals(date)&&old.optJSONArray("offsets").toString().equals(offsets.toString());JSONObject t=old==null?new JSONObject():old;t.put("id",old==null?UUID.randomUUID().toString():id).put("title",title).put("due",date).put("offsets",date.isEmpty()?new JSONArray():offsets).put("priority",priority).put("category",category).put("notes",input.optString("notes","").substring(0,Math.min(4000,input.optString("notes","").length())));if(old==null){t.put("done",false).put("created",java.time.Instant.now().toString());a.put(t);}if(!same)t.put("fired",new JSONArray());write(c,root);return t;}
 public static synchronized void done(Context c,String id,boolean value)throws Exception{JSONObject r=read(c);JSONArray a=r.getJSONArray("tasks");for(int i=0;i<a.length();i++){JSONObject t=a.getJSONObject(i);if(t.optString("id").equals(id))t.put("done",value).put("completed",value?java.time.Instant.now().toString():"");}write(c,r);}
 public static synchronized void delete(Context c,String id)throws Exception{JSONObject r=read(c);JSONArray a=r.getJSONArray("tasks");for(int i=a.length()-1;i>=0;i--)if(a.getJSONObject(i).optString("id").equals(id))a.remove(i);write(c,r);}
 public static String category(JSONObject t){return switch(t.optString("category")){case "research"->"科研";case "work"->"工作";case "study"->"学习";case "life"->"生活";default->"其他";};}
 public static String priority(JSONObject t){return switch(t.optString("priority")){case "high"->"重要";case "low"->"低优先级";default->"普通";};}
 public static void changed(Context c){TodoWidget.updateAll(c);Reminder.schedule(c);CloudSync.schedule(c);}
}
